import java.util.ArrayList;
import java.util.List;
import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        List<Integer> box = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            box.add(sc.nextInt());
        }
        System.out.println("柜子印出来：" + box);
        System.out.println("一共 " + box.size() + " 格");
        System.out.println("编号 1 那格是 " + box.get(1));
        System.out.println("最后一格是 " + box.get(box.size() - 1));
    }
}

