import java.util.ArrayList;
import java.util.List;
import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        List<Integer> box = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            box.add(sc.nextInt());
        }
        int total = 0;
        int cnt = 0;
        for (int x : box) {
            total = total + x;
            if (x >= 4) {
                cnt++;
            }
        }
        System.out.println("柜子里有 " + box.size() + " 格");
        System.out.println("加起来是 " + total);
        System.out.println("不小于 4 的有 " + cnt + " 格");
    }
}

